const raw = $input.item.json;

// Remove extra spaces and newlines from column names
const row = {};

for (const key in raw) {
  row[key.trim().replace(/\n/g, '')] = raw[key];
}

function toNumber(val) {
  if (val === undefined || val === null || val === '') return null;
  const n = Number(String(val).replace(/[^0-9.-]/g, ''));
  return isNaN(n) ? null : n;
}

function toBoolean(val) {
  if (val === undefined || val === null || val === '') return null;
  const v = String(val).trim().toLowerCase();
  if (['yes','true','y'].includes(v)) return true;
  if (['no','false','n'].includes(v)) return false;
  return null;
}

function trimStr(val) {
  return val == null ? '' : String(val).trim();
}

const normalized = {
  timestamp: trimStr(row['Timestamp']),
  travelerId: trimStr(row['Traveler ID']),
  bookingReference: trimStr(row['Booking Reference']),
  fullName: trimStr(row['Full Name']),
  email: trimStr(row['Email']),
  destination: trimStr(row['Destination']),
  travelStartDate: trimStr(row['Travel Start Date']),
  travelEndDate: trimStr(row['Travel End Date']),
  totalBudget: toNumber(row['Total Budget']),
  overallRating: toNumber(row['Overall Rating']),
  hotelRating: toNumber(row['Hotel Rating']),
  transportRating: toNumber(row['Transport Rating']),
  foodRating: toNumber(row['Food Rating']),
  safetyRating: toNumber(row['Safety Rating']),
  destinationRating: toNumber(row['Destination Rating']),
  itineraryUseful: toBoolean(row['Was the itinerary useful?']),
  wouldRecommend: toBoolean(row['Would you recommend us?']),
  favoriteExperience: trimStr(row['Favorite Experience']),
  improvements: trimStr(row['Areas for Improvement']),
  comments: trimStr(row['Additional Comments'])
};

return {
  json: normalized
};

const item = $input.item.json;

let rawText = '';
if (item.message && item.message.content) {
  rawText = item.message.content;
} else if (item.choices && item.choices[0] && item.choices[0].message) {
  rawText = item.choices[0].message.content;
} else if (typeof item.content === 'string') {
  rawText = item.content;
} else if (item.text) {
  rawText = item.text;
} else {
  rawText = JSON.stringify(item);
}

let cleaned = String(rawText).trim();
cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '').trim();

let parsed;
let aiParseFailed = false;

try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  aiParseFailed = true;
  parsed = {
    overallSentiment: 'unknown',
    positiveHighlights: [],
    negativeHighlights: [],
    serviceIssues: [],
    mostAppreciatedFeature: '',
    areasForImprovement: [],
    likelihoodOfReturning: 'unknown',
    customerSatisfactionScore: 0,
    recommendedBusinessActions: [],
    executiveSummary: 'AI response could not be parsed.'
  };
}

return {
  json: {
    aiParseFailed,
    overallSentiment: parsed.overallSentiment ?? 'unknown',
    positiveHighlights: parsed.positiveHighlights ?? [],
    negativeHighlights: parsed.negativeHighlights ?? [],
    serviceIssues: parsed.serviceIssues ?? [],
    mostAppreciatedFeature: parsed.mostAppreciatedFeature ?? '',
    areasForImprovement: parsed.areasForImprovement ?? [],
    likelihoodOfReturning: parsed.likelihoodOfReturning ?? 'unknown',
    customerSatisfactionScore: parsed.customerSatisfactionScore ?? 0,
    recommendedBusinessActions: parsed.recommendedBusinessActions ?? [],
    executiveSummary: parsed.executiveSummary ?? ''
  }
};

const data = $input.item.json;

function daysBetween(start, end) {
  const s = new Date(start);
  const e = new Date(end);
  if (isNaN(s) || isNaN(e)) return null;
  return Math.round((e - s) / (1000 * 60 * 60 * 24));
}

const tripDuration = daysBetween(data.travelStartDate, data.travelEndDate);

const ratingFields = [
  data.hotelRating,
  data.transportRating,
  data.foodRating,
  data.safetyRating,
  data.destinationRating
].filter(r => typeof r === 'number' && !isNaN(r));

const averageRating = ratingFields.length
  ? Number((ratingFields.reduce((a, b) => a + b, 0) / ratingFields.length).toFixed(2))
  : null;

let budgetCategory = 'Unknown';
if (typeof data.totalBudget === 'number') {
  if (data.totalBudget < 30000) budgetCategory = 'Low';
  else if (data.totalBudget < 80000) budgetCategory = 'Medium';
  else budgetCategory = 'High';
}

let customerType = 'Standard';
if (budgetCategory === 'High') customerType = 'Premium';
else if (budgetCategory === 'Low') customerType = 'Budget';

let recommendationScore = 0;
if (typeof data.overallRating === 'number') {
  recommendationScore += (data.overallRating / 5) * 60;
}
if (data.wouldRecommend === true) recommendationScore += 40;
recommendationScore = Math.round(recommendationScore);

const aiScore = typeof data.customerSatisfactionScore === 'number' ? data.customerSatisfactionScore : 0;
const ratingComponent = averageRating !== null ? (averageRating / 5) * 100 : 0;
const overallSatisfactionScore = Math.round((ratingComponent * 0.6) + (aiScore * 0.4));

let returnVisitorProbability = 'Low';
const likelihood = String(data.likelihoodOfReturning || '').toLowerCase();
if (likelihood.includes('high') || data.wouldRecommend === true) {
  returnVisitorProbability = 'High';
} else if (likelihood.includes('medium') || likelihood.includes('moderate')) {
  returnVisitorProbability = 'Medium';
}

const serviceRatings = {
  Hotel: data.hotelRating,
  Transport: data.transportRating,
  Food: data.foodRating,
  Safety: data.safetyRating,
  Destination: data.destinationRating
};

let highestRatedService = 'N/A';
let highestValue = -Infinity;
for (const [service, value] of Object.entries(serviceRatings)) {
  if (typeof value === 'number' && value > highestValue) {
    highestValue = value;
    highestRatedService = service;
  }
}

// NOTE: these Business Insights are computed per-record (single feedback
// response). True cross-customer aggregates (e.g. most popular destination
// across ALL customers) require querying the full Travel Analytics sheet
// history rather than a single trigger event.
const businessInsights = {
  mostPopularDestination: data.destination || 'N/A',
  highestRatedService: highestRatedService,
  mostCommonComplaint: data.improvements || 'None reported',
  averageBudget: typeof data.totalBudget === 'number' ? data.totalBudget : null,
  preferredTravelStyle: budgetCategory
};

return {
  json: {
    ...data,
    tripDuration,
    averageRating,
    budgetCategory,
    customerType,
    recommendationScore,
    overallSatisfactionScore,
    returnVisitorProbability,
    highestRatedService,
    businessInsights
  }
};

const d = $input.item.json;

const status = d.aiParseFailed ? 'Needs Review (AI Parse Failed)' : 'Processed';

const report = `# Travel Feedback Analytics Report

## Traveler Information
- **Name:** ${d.fullName}
- **Traveler ID:** ${d.travelerId}
- **Booking Reference:** ${d.bookingReference}
- **Email:** ${d.email}

## Trip Summary
- **Destination:** ${d.destination}
- **Travel Dates:** ${d.travelStartDate} to ${d.travelEndDate}
- **Trip Duration:** ${d.tripDuration ?? 'N/A'} day(s)
- **Total Budget:** ${d.totalBudget ?? 'N/A'} (${d.budgetCategory})
- **Customer Type:** ${d.customerType}

## Feedback Scores
- **Overall Rating:** ${d.overallRating ?? 'N/A'} / 5
- **Hotel Rating:** ${d.hotelRating ?? 'N/A'} / 5
- **Transport Rating:** ${d.transportRating ?? 'N/A'} / 5
- **Food Rating:** ${d.foodRating ?? 'N/A'} / 5
- **Safety Rating:** ${d.safetyRating ?? 'N/A'} / 5
- **Destination Rating:** ${d.destinationRating ?? 'N/A'} / 5
- **Average Rating:** ${d.averageRating ?? 'N/A'} / 5
- **Highest Rated Service:** ${d.highestRatedService}

## AI Sentiment Analysis
- **Overall Sentiment:** ${d.overallSentiment}
- **Positive Highlights:** ${(d.positiveHighlights || []).join(', ') || 'None'}
- **Negative Highlights:** ${(d.negativeHighlights || []).join(', ') || 'None'}
- **Service Issues:** ${(d.serviceIssues || []).join(', ') || 'None'}
- **Most Appreciated Feature:** ${d.mostAppreciatedFeature || 'N/A'}
- **Customer Satisfaction Score (AI):** ${d.customerSatisfactionScore ?? 'N/A'}
- **Likelihood of Returning:** ${d.likelihoodOfReturning}

## Business Insights
- **Most Popular Destination:** ${d.businessInsights?.mostPopularDestination}
- **Highest Rated Service:** ${d.businessInsights?.highestRatedService}
- **Most Common Complaint:** ${d.businessInsights?.mostCommonComplaint}
- **Average Budget:** ${d.businessInsights?.averageBudget ?? 'N/A'}
- **Preferred Travel Style:** ${d.businessInsights?.preferredTravelStyle}

## Recommendations
${(d.recommendedBusinessActions || []).map(a => `- ${a}`).join('\n') || '- No specific actions recommended.'}

## Executive Summary
${d.executiveSummary || 'N/A'}

## Overall Satisfaction
- **Overall Satisfaction Score:** ${d.overallSatisfactionScore ?? 'N/A'} / 100
- **Recommendation Score:** ${d.recommendationScore ?? 'N/A'} / 100
- **Return Visitor Probability:** ${d.returnVisitorProbability}

## Improvement Suggestions
- **Areas for Improvement (Customer):** ${d.improvements || 'None reported'}
- **Areas for Improvement (AI):** ${(d.areasForImprovement || []).join(', ') || 'None'}
`;

return {
  json: {
    ...d,
    status,
    analyticsReport: report
  }
};

